"""Random request generator covering feasible/infeasible/degenerate shapes."""
import random


def rand_weights(rng, n):
    if n == 0:
        return []
    w = [0] * n
    left = 16
    for i in range(n - 1):
        v = rng.randint(0, left)
        w[i] = v
        left -= v
    w[-1] = left
    if rng.random() < 0.5:
        rng.shuffle(w)
        # keep the sum invariant
        s = sum(w)
        assert s == 16
    return w


def simple_paths(tail, head, src, dst, M, limit=40):
    """Enumerate a few simple directed paths from src to dst."""
    adj = [[] for _ in range(len(tail))]
    for e in range(M):
        adj[tail[e]].append((head[e], e))
    out = []
    stack = [(src, [src], [])]
    seen = set()
    while stack and len(out) < limit:
        node, visited, edges = stack.pop()
        if node == dst:
            key = tuple(edges)
            if key not in seen:
                seen.add(key)
                out.append(list(edges))
            continue
        for h, e in adj[node]:
            if h in visited:
                continue
            stack.append((h, visited + [h], edges + [e]))
    return out


def gen(rng, force=None):
    style = force or rng.choice(["mesh", "dag", "ring", "tiny", "degenerate",
                                 "dense", "sparse-paths"])
    if style == "tiny":
        n = rng.randint(1, 3)
    elif style == "degenerate":
        n = rng.randint(1, 6)
    else:
        n = rng.randint(2, 14)
    M_cap = 384
    edges = []
    if style == "ring":
        for i in range(n):
            j = (i + 1) % n
            if i != j:
                edges.append((i, j, rng.randint(1, 40)))
                if rng.random() < 0.6:
                    edges.append((j, i, rng.randint(1, 40)))
    elif style == "dag":
        for i in range(n):
            for j in range(i + 1, n):
                if rng.random() < 0.35:
                    edges.append((i, j, rng.randint(1, 60)))
                if rng.random() < 0.08:
                    edges.append((j, i, rng.randint(1, 60)))
    elif style == "dense":
        for i in range(n):
            for j in range(n):
                if i != j and rng.random() < 0.7:
                    edges.append((i, j, rng.randint(1, 1024)))
                    if rng.random() < 0.1:
                        edges.append((i, j, rng.randint(1, 1024)))
    elif style == "sparse-paths":
        for i in range(n):
            for j in range(n):
                if i != j and rng.random() < 0.18:
                    edges.append((i, j, rng.randint(1, 20)))
    else:  # mesh / degenerate
        m = rng.randint(0, min(M_cap, max(1, 2 * n))) if style == "degenerate" \
            else rng.randint(n, min(M_cap, max(n, 3 * n)))
        for _ in range(m):
            if n < 2:
                break
            i = rng.randrange(n)
            j = rng.randrange(n)
            if i == j:
                j = (j + 1) % n
                if i == j:
                    continue
            edges.append((i, j, rng.randint(1, 300)))
    edges = edges[:M_cap]
    M = len(edges)
    tail = [e[0] for e in edges]
    head = [e[1] for e in edges]
    caps = [e[2] for e in edges]

    nc = 0 if (style == "degenerate" and rng.random() < 0.3) or n < 2 else \
        rng.randint(0, min(96, 3 * n))
    commodities = []
    total_paths = 0
    used_pairs = set()
    for _ in range(nc):
        if n < 2:
            break
        src = rng.randrange(n)
        dst = rng.randrange(n)
        if src == dst:
            dst = (dst + 1) % n
            if src == dst:
                continue
        paths = simple_paths(tail, head, src, dst, M, limit=60)
        if not paths and rng.random() < 0.6:
            continue
        rng.shuffle(paths)
        npth = min(len(paths), rng.randint(0, 16), 768 - total_paths)
        if npth < 0:
            npth = 0
        chosen = []
        seen = set()
        for p in paths:
            if len(chosen) >= npth:
                break
            key = tuple(p)
            if key in seen:
                continue
            seen.add(key)
            chosen.append(p)
        if rng.random() < 0.12:
            chosen = []
        total_paths += len(chosen)
        dem = rng.choice([0, 0, rng.randint(0, 200), rng.randint(0, 1024)])
        prev = rand_weights(rng, len(chosen))
        commodities.append({"source": src, "target": dst, "demand": dem,
                            "paths": chosen, "previous": prev})
        used_pairs.add((src, dst))
    failed = []
    if M and rng.random() < 0.55:
        nf = rng.randint(0, max(1, M // 3))
        failed = rng.sample(range(M), min(nf, M))
    budget = rng.choice([0, 0, 1, 2, rng.randint(0, 50), rng.randint(0, 2000),
                         rng.randint(0, 98304)])
    req = {"epoch": rng.randint(0, 2147483647), "node_count": n,
           "edges": [{"tail": tail[i], "head": head[i], "capacity": caps[i]}
                     for i in range(M)],
           "commodities": commodities, "failed_edges": failed, "budget": budget}
    return req
