"""Independent re-implementation of the request validation rules (for testing).

Written directly from the task statement, deliberately structured differently
from the submission: a single `valid(obj)` returning True/False.
"""
import json
import math

TOP = ("epoch", "node_count", "edges", "commodities", "failed_edges", "budget")
EDG = ("tail", "head", "capacity")
COM = ("source", "target", "demand", "paths", "previous")


def is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def valid(obj):
    if not isinstance(obj, dict):
        return False
    # duplicate keys are caught by the loader used in `loads_strict`
    for key in TOP:
        if key not in obj:
            return False
    if len(obj) != len(TOP):
        return False

    ep = obj["epoch"]
    if not is_int(ep) or not (0 <= ep <= 2147483647):
        return False
    nc = obj["node_count"]
    if not is_int(nc) or not (1 <= nc <= 96):
        return False

    edges = obj["edges"]
    if not isinstance(edges, list) or len(edges) > 384:
        return False
    for e in edges:
        if not isinstance(e, dict):
            return False
        if set(e.keys()) != set(EDG):
            return False
        for f in EDG:
            if not is_int(e[f]):
                return False
        if not (0 <= e["tail"] < nc and 0 <= e["head"] < nc):
            return False
        if e["tail"] == e["head"]:
            return False
        if not (1 <= e["capacity"] <= 1024):
            return False

    m = len(edges)
    failed = obj["failed_edges"]
    if not isinstance(failed, list):
        return False
    for f in failed:
        if not is_int(f) or not (0 <= f < m):
            return False
    if len(set(failed)) != len(failed):
        return False

    bud = obj["budget"]
    if not is_int(bud) or not (0 <= bud <= 98304):
        return False

    coms = obj["commodities"]
    if not isinstance(coms, list) or len(coms) > 96:
        return False
    total_paths = 0
    for c in coms:
        if not isinstance(c, dict):
            return False
        if set(c.keys()) != set(COM):
            return False
        for f in ("source", "target", "demand"):
            if not is_int(c[f]):
                return False
        if not (0 <= c["source"] < nc and 0 <= c["target"] < nc):
            return False
        if c["source"] == c["target"]:
            return False
        if not (0 <= c["demand"] <= 1024):
            return False
        paths = c["paths"]
        prev = c["previous"]
        if not isinstance(paths, list) or not isinstance(prev, list):
            return False
        if len(paths) > 16:
            return False
        total_paths += len(paths)
        if total_paths > 768:
            return False
        if len(prev) != len(paths):
            return False
        for w in prev:
            if not is_int(w) or not (0 <= w <= 16):
                return False
        if len(paths) > 0 and sum(prev) != 16:
            return False
        seen = []
        for p in paths:
            if not isinstance(p, list) or len(p) == 0:
                return False
            for e in p:
                if not is_int(e) or not (0 <= e < m):
                    return False
            if p in seen:
                return False
            seen.append(p)
            # walk
            node = c["source"]
            order = [node]
            for e in p:
                if edges[e]["tail"] != node:
                    return False
                node = edges[e]["head"]
                if node in order:
                    return False
                order.append(node)
            if node != c["target"]:
                return False
    return True


def loads_strict(text):
    def hook(pairs):
        d = {}
        for k, v in pairs:
            if k in d:
                raise ValueError("dup")
            d[k] = v
        return d

    def const(tok):
        raise ValueError("nonfinite")

    return json.loads(text, object_pairs_hook=hook, parse_constant=const)


def verdict(raw_bytes):
    """Return True when the line should be accepted as a valid request."""
    if len(raw_bytes) > 4 * 1024 * 1024:
        return False
    try:
        text = raw_bytes.decode("utf-8")
    except UnicodeDecodeError:
        return False
    try:
        obj = loads_strict(text)
    except Exception:
        return False
    try:
        return valid(obj)
    except Exception:
        return False
