"""Byte-level corruption fuzzer: planner must never crash and must agree
with the reference validator on every corrupted line."""
import json, random, subprocess, sys
sys.path.insert(0, "/app/work")
import gen, gen2, refvalid

PLANNER = "/app/submission/planner.py"
ALPHABET = b'{}[]",:0123456789.eE+-truefalsnul \t\r\n\\/abcXYZ'


def corrupt(rng, raw):
    b = bytearray(raw.rstrip(b"\n"))
    ops = rng.randint(1, 3)
    for _ in range(ops):
        if not b:
            break
        kind = rng.randrange(5)
        i = rng.randrange(len(b))
        if kind == 0:
            del b[i]
        elif kind == 1:
            b.insert(i, rng.choice(ALPHABET))
        elif kind == 2:
            b[i] = rng.choice(ALPHABET)
        elif kind == 3:
            j = min(len(b), i + rng.randint(1, 30))
            del b[i:j]
        else:
            j = min(len(b), i + rng.randint(1, 20))
            b[i:j] = b[i:j][::-1]
    if rng.random() < 0.3:
        # make sure it is a single line
        b = bytearray(bytes(b).replace(b"\n", b" ").replace(b"\r", b" "))
    return bytes(b)


def main(seed, n):
    rng = random.Random(seed)
    bases = []
    for _ in range(n):
        bases.append(json.dumps(gen.gen(rng) if rng.random() < 0.5 else gen2.gen(rng)).encode())
    lines = []
    for raw in bases:
        lines.append(raw)
        for _ in range(6):
            c = corrupt(rng, raw)
            if b"\n" in c or b"\r" in c:
                c = c.replace(b"\n", b" ").replace(b"\r", b" ")
            lines.append(c)
        lines.append(corrupt(rng, raw).replace(b"\n", b" ").replace(b"\r", b" "))
    payload = b"".join(l + b"\n" for l in lines)
    p = subprocess.run([sys.executable, PLANNER], input=payload,
                       capture_output=True, timeout=800)
    if p.returncode != 0:
        print("CRASH rc=%s" % p.returncode, p.stderr.decode()[-2000:])
        return 1
    out = p.stdout.decode(errors="replace").splitlines()
    if len(out) != len(lines):
        print("count mismatch", len(out), len(lines)); return 1
    fails = 0
    nvalid = 0
    for raw, line in zip(lines, out):
        try:
            resp = json.loads(line)
        except Exception:
            print("non-JSON response for %r" % raw[:120]); fails += 1; continue
        if set(resp.keys()) != {"status"} and resp.get("status") == "invalid":
            print("bad invalid shape", resp); fails += 1
        mine_invalid = resp.get("status") == "invalid"
        ref_invalid = not refvalid.verdict(raw + b"\n")
        if mine_invalid != ref_invalid:
