            if fails < 10:
                print("DISAGREE planner_invalid=%s ref_invalid=%s line=%r" %
                      (mine_invalid, ref_invalid, raw[:300]))
        if not mine_invalid:
            nvalid += 1
    print("text fuzz: %d lines, %d disagreements, %d accepted as valid" %
          (len(lines), fails, nvalid))
    if p.stderr.strip():
        print("stderr sample:", p.stderr.decode()[:300])
    return fails


if __name__ == "__main__":
    sys.exit(1 if main(int(sys.argv[1]), int(sys.argv[2])) else 0)
