PRIMAL_GATE = 5.0e-6
DUAL_COL_GATE = 1.0e-9
DUAL_GAP_GATE = 1.0e-5


def _candidate(model, prob, res):
    """Build a (violation, payload) pair from a primal LP result, or None."""
    if res is None or res.x is None:
        return None
    x = np.asarray(res.x, dtype=np.float64)
    if x.size != model.n or not np.all(np.isfinite(x)):
        return None
    flows, loads, mlu, migration = _allocation(model, x)
    if not (np.isfinite(mlu) and np.isfinite(migration)):
