def _payload_clean(payload, model):
    """Score a payload: (dual column slack, |mlu - L|, primal violation)."""
    y = np.array(payload["dual"]["inequality"], dtype=np.float64)
    q = np.array(payload["dual"]["equality"], dtype=np.float64)
