    return (colv, gap, viol)


def solve(prob):
    model = Model(prob)
    attempts = (
        {"tight": False, "presolve": True, "limit": 30.0,
         "methods": ("highs",)},
        {"tight": True, "presolve": True, "limit": 12.0,
