                "planner: weak certificate colv=%.3g gap=%.3g viol=%.3g\n"
                % (colv, gap, viol))
        return best[1]
    if saw_infeasible:
        raise Invalid("infeasible without witness")
    raise Invalid("solver failure")


def _nest(flows, shapes):
    out = []
    idx = 0
    for count in shapes:
        out.append([flows[idx + i] for i in range(count)])
        idx += count
    return out


